require __DIR__.'/app/bootstrap.php';$pageTitle='Nama Pemenang';$pageDescription='Perjalanan pemenang Bujang Dayang Bangka Belitung dari tahun ke tahun.';$year=(int)($_GET['year']??0);$sql="SELECT w.*, rb.name bujang_region, rd.name dayang_region FROM winners w LEFT JOIN regions rb ON rb.id=w.bujang_region_id LEFT JOIN regions rd ON rd.id=w.dayang_region_id WHERE w.is_published=1";$params=[];if($year){$sql.=' AND w.year=?';$params[]=$year;}$sql.=' ORDER BY w.year DESC';$stmt=db()->prepare($sql);$stmt->execute($params);$winners=$stmt->fetchAll();$years=db()->query('SELECT DISTINCT year FROM winners WHERE is_published=1 ORDER BY year DESC')->fetchAll(PDO::FETCH_COLUMN);require __DIR__.'/views/partials/header.php';
?>
<section class="py-5 bg-emerald text-white"><div class="container py-4"><div class="row align-items-end g-4"><div class="col-lg-8"><div class="section-kicker text-gold">Jejak Inspirasi</div><h1 class="display-3 fw-bold mb-3">Perjalanan Para Pemenang</h1><p class="text-white-50 fs-5 mb-0">Mengenang Bujang dan Dayang terpilih yang telah membawa nama Bangka Belitung melalui karya, pengabdian, dan promosi daerah.</p></div><div class="col-lg-4"><form class="d-flex gap-2"><select class="form-select form-select-lg" name="year"><option value="">Semua Tahun</option><?php foreach($years as $y):?><option value="<?= (int)$y ?>" <?= $year===(int)$y?'selected':'' ?>><?= (int)$y ?></option><?php endforeach;?></select><button class="btn btn-gold px-4">Tampilkan</button></form></div></div></div></section>
<section class="section-space"><div class="container"><div class="timeline"><?php foreach($winners as $i=>$w):?><div class="timeline-item"><span class="timeline-dot"></span><div class="row g-4 align-items-center <?= $i%2?'flex-row-reverse':'' ?>"><div class="col-lg-5 <?= $i%2?'':'offset-lg-1' ?>"><div class="winner-card"><span class="year-badge mb-4"><?= (int)$w['year'] ?></span><div class="row g-3"><div class="col-6"><div class="winner-photo"><img src="<?= upload_url($w['bujang_photo'],'images/placeholder-bujang.svg') ?>" alt="<?= e($w['bujang_name']) ?>"></div><div class="text-center mt-3"><span class="small text-uppercase text-gold fw-bold">Bujang</span><h4 class="mb-1"><?= e($w['bujang_name']) ?></h4><div class="small text-secondary"><?= e($w['bujang_region']) ?></div></div></div><div class="col-6"><div class="winner-photo"><img src="<?= upload_url($w['dayang_photo'],'images/placeholder-dayang.svg') ?>" alt="<?= e($w['dayang_name']) ?>"></div><div class="text-center mt-3"><span class="small text-uppercase text-gold fw-bold">Dayang</span><h4 class="mb-1"><?= e($w['dayang_name']) ?></h4><div class="small text-secondary"><?= e($w['dayang_region']) ?></div></div></div></div></div></div><div class="col-lg-5"><div class="px-lg-4"><div class="section-kicker"><?= e($w['theme'] ?: 'Bujang Dayang Bangka Belitung') ?></div><h2 class="font-display display-5 fw-bold text-emerald">Tahun <?= (int)$w['year'] ?></h2><p class="text-secondary"><?= nl2br(e($w['description'] ?: 'Pemenang tahun ini menjadi representasi generasi muda Bangka Belitung dalam promosi budaya, pariwisata, dan kreativitas daerah.')) ?></p><?php if($w['documentation_url']):?><a class="btn btn-outline-success rounded-pill" target="_blank" rel="noopener" href="<?= e($w['documentation_url']) ?>"><i class="bi bi-images me-2"></i>Lihat Dokumentasi</a><?php endif;?></div></div></div></div><?php endforeach;?><?php if(!$winners):?><div class="empty-state"><i class="bi bi-trophy fs-1 text-emerald"></i><h4 class="mt-3">Data pemenang belum tersedia</h4><p class="text-secondary">Superadmin dapat menambahkan riwayat pemenang melalui dashboard.</p></div><?php endif;?></div></div></section>
